mapper.insert:
insert into competition_scene_subject_operation_state
(competition_series_id, scope_type, scope_ref_id, subject_type, subject_code, operation_type,
 operation_status, operation_time, credential_id, operator_user_id, operator_name,
 delegate_user_id, delegate_name, delegate_credential_id, delegate_relation, last_log_id,
 remark, create_by, create_time, update_by, update_time, deleted)
select #{competitionSeriesId}, #{scopeType}, #{scopeRefId}, #{subjectType}, #{subjectCode}, #{operationType},
       'DONE', #{operationTime}, #{credentialId}, #{operatorUserId}, #{operatorName},
       #{delegateUserId}, #{delegateName}, #{delegateCredentialId}, #{delegateRelation}, #{lastLogId},
       #{remark}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, 0
from dual
where not exists (
    select 1
    from competition_scene_subject_operation_state
    where competition_series_id = #{competitionSeriesId}
      and scope_type = #{scopeType}
      and scope_ref_id = #{scopeRefId}
      and subject_type = #{subjectType}
      and subject_code = #{subjectCode}
      and operation_type = #{operationType}
      and operation_status = 'DONE'
      and deleted = 0
)

mapper.update:
update competition_scene_subject_operation_state
set operation_status = 'CANCELLED',
    update_by = #{updateBy},
    update_time = now()
where deleted = 0
  and operation_status = 'DONE'
  and competition_series_id = #{query.competitionSeriesId}
  and scope_type = #{query.scopeType}
  and scope_ref_id = #{query.scopeRefId}
  and subject_type = #{query.subjectType}
  and subject_code = #{query.subjectCode}
  and operation_type = #{query.operationType}
